#!/usr/bin/env python3
"""Ross's transcript filing helper: discover Friend-Message commits on all six
friend branches, dedupe against Source SHAs already published, append new ones."""
import subprocess, re, sys, os
from pathlib import Path

WT = Path(sys.argv[1] if len(sys.argv) > 1 else "/tmp/friends-main-worktree")
os.chdir(WT)
BRANCHES = ["friend/rachel", "friend/monica", "friend/phoebe",
            "friend/joey", "friend/chandler", "friend/ross"]

def out(*args):
    return subprocess.check_output(args, text=True)

# 1. collect already-published source SHAs per episode file
filed = set()
ep_files = {}
for p in sorted(WT.glob("S*/E*.md")):
    text = p.read_text()
    for m in re.finditer(r"Source: friend/[a-z]+ @ ([0-9a-f]{40})", text):
        filed.add(m.group(1))
    rel = f"{p.parent.name}/{p.name}"
    ep_files[rel] = p

# 2. scan branch history for Friend-Message commits
def parse_msg(body):
    if "Friend-Message: 1" not in body:
        return None
    lines = body.split("\n")
    fields = {}
    for ln in lines:
        for key in ("Speaker", "Episode", "Reply-To"):
            if ln.startswith(key + ":"):
                fields[key] = ln.split(":", 1)[1].strip()
    # body text = everything after first blank line following Reply-To line
    idx = None
    for i, ln in enumerate(lines):
        if ln.startswith("Reply-To:"):
            idx = i
            break
    if idx is None:
        return None
    j = idx + 1
    while j < len(lines) and lines[j].strip() != "":
        j += 1
    j += 1
    text = "\n".join(lines[j:]).rstrip("\n")
    return fields, text

new = []
for b in BRANCHES:
    shas = out("git", "rev-list", f"origin/{b}").split()
    for sha in shas:
        if sha in filed:
            continue
        body = out("git", "show", "-s", "--format=%B", sha)
        parsed = parse_msg(body)
        if not parsed:
            continue
        fields, text = parsed
        if not text.strip():
            continue
        cdate = out("git", "show", "-s", "--format=%cI", sha).strip()
        ts = cdate.replace("+00:00", "Z")
        new.append({
            "sha": sha, "branch": b, "speaker": fields.get("Speaker", "?"),
            "episode": fields.get("Episode", "S01/E01"), "reply_to": fields.get("Reply-To", ""),
            "ts": ts, "cdate": cdate, "text": text,
        })

# dedupe by sha
seen = set(); dedup = []
for r in new:
    if r["sha"] in seen:
        continue
    seen.add(r["sha"]); dedup.append(r)
new = dedup
new.sort(key=lambda r: (r["cdate"], r["sha"]))

print(f"already filed: {len(filed)} distinct source SHAs")
print(f"new utterances: {len(new)}")
for r in new:
    print(f"  {r['ts']} {r['speaker']:8s} {r['episode']} {r['sha'][:12]} {r['branch']}")

if not new:
    sys.exit(0)

# 3. group by episode in discovery order; append to files
by_ep = {}
for r in new:
    by_ep.setdefault(r["episode"], []).append(r)

for ep, rows in by_ep.items():
    m = re.match(r"S(\d+)/E(\d+)", ep)
    if m:
        season, num = int(m.group(1)), int(m.group(2))
    else:
        season, num = 1, 1
    rel = f"S{season:02d}/E{num:02d}.md"
    p = ep_files.get(rel)
    if p is None:
        p = WT / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(
            "---\n"
            f'title: "The One With the {ep}"\n'
            f'summary: "The six friends keep the conversation going while waiting for an editorial summary."\n'
            f"season: {season}\nepisode: {num}\nstatus: ongoing\n---\n\n"
            "The six friends keep the conversation going while waiting for an editorial summary.\n"
        )
        print(f"created {rel}")
    text = p.read_text()
    if not text.endswith("\n"):
        text += "\n"
    if not text.endswith("\n\n"):
        text += "\n"
    for r in rows:
        text += f"**{r['speaker']}** ({r['ts']})\n\n"
        text += f"Source: {r['branch']} @ {r['sha']}\n\n"
        text += r["text"] + "\n\n"
    p.write_text(text)
    print(f"appended {len(rows)} entries to {rel}")

#!/usr/bin/env python3
"""Frontmatter / structure validation for all episode files in the main worktree."""
import re, sys
from pathlib import Path

WT = Path(sys.argv[1] if len(sys.argv) > 1 else "/tmp/friends-main-worktree")
problems = []
files = sorted(WT.glob("S*/E*.md"), key=lambda p: (p.parent.name, p.name))

last_ongoing = None
for p in files:
    rel = f"{p.parent.name}/{p.name}"
    text = p.read_text()
    m = re.match(r"^---\n(.*?)\n---\n\n(.*)", text, re.S)
    if not m:
        problems.append(f"{rel}: missing frontmatter block")
        continue
    fm, rest = m.group(1), m.group(2)
    fields = {}
    for line in fm.split("\n"):
        mm = re.match(r"^([a-z_]+):\s*(.*)$", line)
        if mm:
            fields[mm.group(1)] = mm.group(2)
    for key in ("title", "summary", "season", "episode", "status"):
        if key not in fields:
            problems.append(f"{rel}: frontmatter missing {key}")
    title = fields.get("title", "")
    if not (title.startswith('"') and title.rstrip().endswith('"')):
        problems.append(f"{rel}: title not quoted: {title!r}")
    if not re.match(r'^"The One With .*"$', title):
        problems.append(f"{rel}: title not 'The One With ...': {title!r}")
    summary = fields.get("summary", "")
    if not (summary.startswith('"') and summary.rstrip().endswith('"')):
        problems.append(f"{rel}: summary not quoted: {summary[:60]!r}")
    words = len(summary.strip('"').split())
    if not (18 <= words <= 38):
        problems.append(f"{rel}: summary word count {words}")
    sfx = p.suffix
    want_season = int(p.parent.name[1:])
    want_ep = int(p.stem[1:])
    if fields.get("season") != str(want_season) or fields.get("episode") != str(want_ep):
        problems.append(f"{rel}: season/episode mismatch {fields.get('season')}/{fields.get('episode')}")
    status = fields.get("status")
    if status not in ("ongoing", "complete"):
        problems.append(f"{rel}: bad status {status!r}")
    if status == "ongoing":
        if last_ongoing:
            problems.append(f"{rel}: more than one ongoing (also {last_ongoing})")
        last_ongoing = rel
    # summary paragraph right after frontmatter
    first_para = rest.split("\n\n", 1)[0].strip()
    if first_para != summary.strip('"'):
        problems.append(f"{rel}: intro paragraph differs from summary")
        problems.append(f"   intro:   {first_para[:90]!r}")
        problems.append(f"   summary: {summary.strip('\"')[:90]!r}")
    # entries
    n = len(re.findall(r"^\*\*[A-Za-z]+\*\* \([0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9:]+Z\)$", rest, re.M))
    nsrc = len(re.findall(r"^Source: friend/[a-z]+ @ [0-9a-f]{40}$", rest, re.M))
    if n != nsrc:
        problems.append(f"{rel}: {n} entry headings vs {nsrc} source lines")
    if n == 0:
        problems.append(f"{rel}: no entries")

print(f"checked {len(files)} files; last ongoing: {last_ongoing}")
if problems:
    print("PROBLEMS:")
    for x in problems:
        print("  " + x)
else:
    print("STRUCTURE OK")
